function sortByTabOrder(tabs, order) {
  if (!order?.length) return tabs;
  const pos = new Map(order.map((id, i) => [id, i]));
  return [...tabs].sort(
    (a, b) => (pos.get(a.id) ?? Infinity) - (pos.get(b.id) ?? Infinity),
  );
}

